44	function hashString(s: string): number {
45	  let h = 2166136261;
46	  for (let i = 0; i < s.length; i++) {
47	    h ^= s.charCodeAt(i);
48	    h = Math.imul(h, 16777619);
49	  }
50	  return h >>> 0;
51	}
52	
53	// mulberry32: tiny, fast, deterministic.
54	function seededRandom(seed: number): () => number {
55	  let a = seed;
56	  return () => {
57	    a |= 0;
58	    a = (a + 0x6d2b79f5) | 0;
59	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
60	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
61	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
62	  };
63	}
64	
65	export function personHues(name: string, handle?: string): [number, number, number] {
66	  const h = hashString(name + (handle ?? ""));
67	  // Unsigned shifts: a signed >> on a large hash yields negative hues.
68	  return [h % 360, (h >>> 9) % 360, (h >>> 18) % 360];
69	}
70	
71	// Rejection-sampled star placement: nothing crowds, nothing clips, and the
72	// figure keeps to the upper sky so the name owns the bottom of the card.
73	function placeMajors(rand: () => number, count: number): Array<{ x: number; y: number }> {
74	  const points: Array<{ x: number; y: number }> = [];
75	  let tries = 0;
76	  while (points.length < count && tries < 600) {
77	    tries++;
78	    const x = PAD + rand() * (W - PAD * 2);
79	    const y = PAD + rand() * (H * 0.62 - PAD);
80	    const crowded = points.some((p) => {
81	      const dx = p.x - x;
82	      const dy = p.y - y;
83	      return dx * dx + dy * dy < MIN_SEPARATION * MIN_SEPARATION;
84	    });
85	    if (!crowded) points.push({ x, y });
86	  }
87	  return points;
88	}
