21	    /// last one or two majors are ambient figure stars. They read as always lit:
22	    /// an ambient star has no field behind it, so dimming it would be a nudge
23	    /// pointing at nothing, and the person could never switch it on.
24	    static func litMajorIndices(filled: Set<StarSlot>, majorCount: Int) -> Set<Int> {
